// n8n Code node: "Validate payload"
// Bubble sends the author's full royalty data in the webhook body (the free
// plan blocks incoming API calls, so n8n can't fetch it from Bubble's Data API).
const body = $input.first().json.body ?? {};
const errors = [];

if (!body.request_id) errors.push("request_id is required");
if (!body.author || !body.author.name) errors.push("author.name is required");
if (!body.author || !body.author.code) errors.push("author.code is required");

let books = body.books;
// Bubble builds the list as a JSON string; accept either form.
if (typeof books === "string") {
  try {
    books = JSON.parse(books.trim().startsWith("[") ? books : `[${books}]`);
  } catch (e) {
    errors.push(`books is not valid JSON: ${e.message}`);
  }
}
if (!Array.isArray(books)) errors.push("books must be a list");

const num = (v) => (v === null || v === undefined || v === "" ? 0 : Number(v));
// Platforms arrive as a list or a comma-separated string; normalise to a list.
const list = (v) => (Array.isArray(v) ? v : String(v ?? "").split(",")).map((s) => String(s).trim()).filter(Boolean);

return [
  {
    json: {
      valid: errors.length === 0,
      error_message: errors.join("; "),
      request_id: body.request_id ?? null,
      triggered_by: body.triggered_by ?? null,
      author: body.author ?? {},
      books: (Array.isArray(books) ? books : []).map((b) => ({
        code: b.code,
        title: b.title,
        stage: b.stage,
        publication_date: b.publication_date || null,
        mrp: num(b.mrp),
        copies_sold: num(b.copies_sold),
        royalty_earned: num(b.royalty_earned),
        royalty_paid: num(b.royalty_paid),
        royalty_pending: num(b.royalty_pending),
        last_payout_date: b.last_payout_date || null,
        available_on: list(b.available_on),
      })),
    },
  },
];

// n8n Code node: "Deduplicate"
// Second line of defence against double clicks (Bubble also blocks a second
// trigger while one is Processing). Remembers the last request per author in
// workflow static data; a different request for the same author within the
// window is rejected. Static data persists between production executions.
const WINDOW_SECONDS = 120;
const item = $input.first().json;
const store = $getWorkflowStaticData("global");
store.recent = store.recent ?? {};

const now = Date.now();
// Forget old entries so the store doesn't grow forever.
for (const [key, entry] of Object.entries(store.recent)) {
  if (now - entry.at > WINDOW_SECONDS * 1000) delete store.recent[key];
}

const key = item.author.code;
const previous = store.recent[key];
const duplicate = Boolean(previous && previous.request_id !== item.request_id);

if (!duplicate) store.recent[key] = { request_id: item.request_id, at: now };

return [
  {
    json: {
      ...item,
      duplicate,
      error_message: duplicate
        ? `Duplicate request ignored: a summary for ${item.author.name} was started ${Math.round((now - previous.at) / 1000)}s ago (request ${previous.request_id}).`
        : "",
    },
  },
];

// n8n Code node: "Compute royalty facts & build prompt"
// All arithmetic and dates are computed here, deterministically, and handed to
// the model as facts. The model writes prose; it never does calendar maths.
const SYSTEM_PROMPT = "You write royalty summary emails for BookLeaf Publishing, a self-publishing company in India and the US. The email goes to one author and summarises their books, sales and royalties. Write the exact email an author would receive from the BookLeaf Author Support team.\n\n<knowledge_base>\nRoyalty policy:\n- 80/20 split: 80% of the net profit per book goes to the author. Net profit = MRP minus printing cost, platform commission (Amazon/Flipkart) and shipping.\n- Royalties are calculated quarterly and paid within 45 days of the quarter ending, by bank transfer to the account linked in the author's dashboard.\n- Minimum payout threshold: ₹1,000. Accumulated royalties below this roll over to the next quarter.\n- Authors can see a per-platform royalty breakdown in their dashboard.\nProduction stages: Manuscript Received → Editing → Cover Design → Typesetting → Proofreading → ISBN Assignment → Printing → Distribution Setup → Published & Live. Authors are emailed at each stage; Cover Design and Proofreading usually take longest because they need author approval.\n</knowledge_base>\n\n<tone>\n- Empathetic and professional: authors are partners, not customers to be managed.\n- Specific: use the exact figures, dates and statuses from <royalty_facts>; no vague reassurance.\n- If a payout is overdue, that is BookLeaf's fault: say so plainly, apologise once, and give a clear timeline (\"our finance team will confirm your payout date within 48 hours\").\n- End with a clear next step.\n</tone>\n\n<rules>\n- Use ONLY the facts in <royalty_facts>. Never invent figures, dates, platforms or stages. Only name a sales platform if it appears in that book's available_on list; if you mention the per-platform breakdown, do not name platforms at all. Amounts are Indian rupees; write them like ₹3,570.\n- Greet the author by first name.\n- For each published book: one or two lines with copies sold, royalty earned, paid and pending.\n- Give the account totals: total earned, total paid, total pending (use the totals provided).\n- Pending money: explain when it will be paid using next_payout_by and the quarterly cycle. If below_threshold is true, explain the ₹1,000 rollover instead. If a book is overdue, acknowledge it and give the 48-hour finance follow-up.\n- Nothing pending: thank them and acknowledge that they are fully paid up.\n- Books still in production: a short status line with the current stage and what comes next. Never mention sales or royalties for them.\n- Write dates as they appear in the facts. Don't convert durations into calendar dates.\n- Sign off exactly as:\n  Warm regards,\n  The BookLeaf Author Support Team\n- Plain text only: no markdown, no bullet characters or asterisks. Short paragraphs separated by a blank line. 180–320 words.\n- subject: specific and friendly, e.g. \"Your BookLeaf royalty summary — ₹3,570 pending\".\n</rules>";
const MODEL = "gemini-3.5-flash";
const PAYOUT_THRESHOLD = 1000;
const PAYOUT_WINDOW_DAYS = 45;
const OVERDUE_DAYS = 90; // brief A2: overdue if last payout > 90 days ago (or never paid, published > 90 days ago)
// Dataset emails are real-looking addresses on a public provider, so every email
// is redirected to a safe inbox. The intended recipient is kept in the log/email.
const SAFE_RECIPIENT = "jash2884@gmail.com";

const item = $input.first().json;
const today = new Date(new Date().toISOString().slice(0, 10) + "T00:00:00Z");
const DAY = 86400000;
const daysSince = (d) => Math.floor((today - new Date(d + "T00:00:00Z")) / DAY);
const inr = (n) => "₹" + Number(n).toLocaleString("en-IN");
const fmt = (d) => new Date(d).toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric", timeZone: "UTC" });

// Next payout: the previous quarter's deadline (quarter end + 45 days) if it hasn't passed, else this quarter's.
const quarterEnd = (d) => new Date(Date.UTC(d.getUTCFullYear(), Math.floor(d.getUTCMonth() / 3) * 3 + 3, 0));
const thisQEnd = quarterEnd(today);
const prevQEnd = new Date(Date.UTC(thisQEnd.getUTCFullYear(), thisQEnd.getUTCMonth() - 2, 0));
const deadline = (q) => new Date(q.getTime() + PAYOUT_WINDOW_DAYS * DAY);
const settles = today <= deadline(prevQEnd) ? prevQEnd : thisQEnd;
const quarterName = (q) => `Q${Math.floor(q.getUTCMonth() / 3) + 1} ${q.getUTCFullYear()}`;

const STAGES = ["Manuscript Received", "Editing", "Cover Design", "Typesetting", "Proofreading", "ISBN Assignment", "Printing", "Distribution Setup", "Published & Live"];

const books = item.books.map((b) => {
  const published = b.stage === "Published & Live";
  if (!published) {
    const i = STAGES.indexOf(b.stage);
    return { title: b.title, status: "In production", current_stage: b.stage, next_stages: i >= 0 ? STAGES.slice(i + 1).join(" → ") : "" };
  }
  let royalty_status = "Paid up";
  if (b.royalty_pending > 0) {
    const ref = b.last_payout_date ?? b.publication_date;
    royalty_status = ref && daysSince(ref) > OVERDUE_DAYS ? "Overdue" : "Pending";
  }
  return {
    title: b.title,
    status: "Published & Live",
    published_on: b.publication_date ? fmt(b.publication_date) : null,
    copies_sold: b.copies_sold,
    royalty_earned: inr(b.royalty_earned),
    royalty_paid: inr(b.royalty_paid),
    royalty_pending: inr(b.royalty_pending),
    last_payout: b.last_payout_date ? fmt(b.last_payout_date) : "never paid yet",
    available_on: b.available_on ?? [],
    royalty_status,
  };
});

const sum = (k) => item.books.reduce((s, b) => s + (b[k] || 0), 0);
const pending = sum("royalty_pending");
// Policy beats the 90-day heuristic: an account total under ₹1,000 isn't overdue, it rolls over.
if (pending > 0 && pending < PAYOUT_THRESHOLD) {
  for (const b of books) if (b.royalty_status === "Overdue" || b.royalty_status === "Pending") b.royalty_status = "Below ₹1,000 threshold — rolls over";
}
const facts = {
  author_first_name: String(item.author.name).split(" ")[0],
  author_name: item.author.name,
  today: fmt(today),
  books,
  totals: { earned: inr(sum("royalty_earned")), paid: inr(sum("royalty_paid")), pending: inr(pending) },
  fully_paid_up: pending === 0,
  below_threshold: pending > 0 && pending < PAYOUT_THRESHOLD,
  any_overdue: books.some((b) => b.royalty_status === "Overdue"),
  next_payout_by: fmt(deadline(settles)),
  next_payout_covers: quarterName(settles),
  payout_threshold: inr(PAYOUT_THRESHOLD),
};
// Every platform any of the author's published books is sold on (for the platform guardrail).
const platforms = [...new Set(books.flatMap((b) => b.available_on ?? []))];

const user = `<royalty_facts>\n${JSON.stringify(facts, null, 2)}\n</royalty_facts>\n\nWrite the royalty summary email for ${facts.author_name}.`;

const gemini_request = {
  systemInstruction: { parts: [{ text: SYSTEM_PROMPT }] },
  contents: [{ role: "user", parts: [{ text: user }] }],
  generationConfig: {
    responseMimeType: "application/json",
    responseJsonSchema: {
      type: "object",
      properties: {
        subject: { type: "string", description: "Email subject line" },
        body: { type: "string", description: "Plain-text email body" },
      },
      required: ["subject", "body"],
    },
    maxOutputTokens: 4096,
    thinkingConfig: { thinkingLevel: "LOW" },
  },
};

return [
  {
    json: {
      ...item,
      facts,
      model: MODEL,
      gemini_request,
      recipient_email: SAFE_RECIPIENT,
      intended_recipient: item.author.email,
      expected_pending_text: inr(pending),
      allowed_platforms: platforms,
    },
  },
];

// n8n Code node: "Parse & check AI output"
// Validates the model's JSON and runs cheap guardrails before anything is
// emailed: the author's name and the exact pending total must appear.
const ctx = $("Compute royalty facts").first().json;
const res = $input.first().json;

let email = null;
let problem = "";
try {
  const text = res.candidates?.[0]?.content?.parts?.map((p) => p.text ?? "").join("") ?? "";
  const finish = res.candidates?.[0]?.finishReason;
  if (finish && finish !== "STOP") throw new Error(`model stopped early (${finish})`);
  email = JSON.parse(text);
  if (!email.subject || !email.body) throw new Error("missing subject or body");
  if (!email.body.includes(ctx.facts.author_first_name)) throw new Error("email does not greet the author by name");
  if (!email.body.includes(ctx.expected_pending_text)) throw new Error(`email does not state the pending total ${ctx.expected_pending_text}`);
  // Platform check: any store the email names must be one the author's books are actually sold on.
  const allowed = ctx.allowed_platforms ?? [];
  const mailText = `${email.subject}\n${email.body}`;
  for (const p of ["Flipkart", "Amazon US", "Amazon UK", "Amazon India", "BookLeaf Store"]) {
    if (mailText.includes(p) && !allowed.includes(p)) throw new Error(`email names platform "${p}", which this author's books are not sold on`);
  }
  if (/\bAmazon\b/.test(mailText) && !allowed.some((p) => p.startsWith("Amazon"))) throw new Error('email names "Amazon", which this author\'s books are not sold on');
} catch (e) {
  problem = `AI output rejected: ${e.message}`;
}

const footer = `\n\n—\nDemo note: this message was addressed to ${ctx.intended_recipient} and redirected to a test inbox.`;

return [
  {
    json: {
      ok: !problem,
      error_message: problem,
      request_id: ctx.request_id,
      author_code: ctx.author.code,
      subject: email?.subject ?? "",
      body: email?.body ?? "",
      email_text: email ? email.body + footer : "",
      recipient_email: ctx.recipient_email,
      intended_recipient: ctx.intended_recipient,
      model: res.modelVersion ?? ctx.model,
    },
  },
];
